style.css:
/* GLOBAL BLACK + SOFT PINK THEME — FIXED VERSION */

:root {
  --bg-main: #0d0d0d; /* Black background */
  --text-main: #ffd8ea; /* Soft pink text */
  --pink-accent: #ffb6d5; /* Pink accent color */
  --input-bg: #1a1a1a; /* Dark input background */
  --link-hover: #ffffff; /* White hover color for links */
}

/* Safe background and text */
html, body {
  background-color: var(--bg-main) !important;
  color: var(--text-main) !important;
}

/* Text elements */
h1, h2, h3, h4, h5, h6, p, span, a, div, li, td, th, label {
  color: var(--text-main) !important;
}

/* Links */
a {
  color: var(--pink-accent) !important;
}
a:hover {
  color: var(--link-hover) !important;
}

/* Inputs & Forms */
input, textarea, select, button {
  background-color: var(--input-bg) !important;
  color: var(--text-main) !important;
  border: 1px solid var(--pink-accent) !important;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-thumb {
  background: var(--pink-accent);
  border-radius: 10px;
}
::-webkit-scrollbar-track {
  background: var(--bg-main);
}

/* Media elements — ensure proper visibility */
img, video, picture, svg, canvas, iframe {
  filter: none !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* Prevent layout issues for media */
img, video, iframe, canvas, picture, svg {
  display: inline-block !important; /* Fix layout issues */
}

/* Containers for media elements */
[class*="image"], [class*="media"], [class*="thumb"], [class*="photo"], [class*="img"], [class*="pin"] {
  background-color: transparent !important; /* Avoid black overlays */
}

/* Section backgrounds — avoid black screens */
div, section, article, aside, header, footer, nav, main {
  background-color: var(--bg-main) !important; /* Consistent dark theme */
}

/* Borders for all elements */
* {
  border-color: var(--pink-accent) !important;
}
